use parth_db::exec::{bounded_rows, execute};
use parth_db::value::Value;
use parth_db::Database;

#[test]
fn oversized_transaction_is_rejected_and_rolled_back() { let dir = std::env::temp_dir().join(format!("parth_overlay_{}", std::process::id())); let _ = std::fs::remove_dir_all(&dir); let db = Database::open(&dir).unwrap(); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, v TEXT)").unwrap(); for i in 1..=200 { execute(&db, &format!("INSERT INTO t VALUES ({}, 'x{}')", i, i)).unwrap(); } let sql = format!("UPDATE t SET v = '{}'", "y".repeat(60000)); let result = db.transaction(true, |tx| { for _ in 0..20 { execute(tx, &sql)?; } Ok(()) }); assert!(result.is_err()); let rows = bounded_rows(&db, "t", usize::MAX, usize::MAX).unwrap(); assert_eq!(rows.len(), 200); assert_eq!(rows[0][1], Value::Text("x1".to_string())); let _ = std::fs::remove_dir_all(&dir); }

#[test]fn transaction_under_limit_commits_then_over_limit_rolls_back() { let dir = std::env::temp_dir().join(format!("parth_overlay_near_{}", std::process::id())); let _ = std::fs::remove_dir_all(&dir); let db = Database::open(&dir).unwrap(); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY, v TEXT)").unwrap(); for i in 1..=200 { execute(&db, &format!("INSERT INTO t VALUES ({}, 'x{}')", i, i)).unwrap(); } let big = |c: &str| format!("UPDATE t SET v = '{}'", c.repeat(60000)); let ok = db.transaction(true, |tx| { for _ in 0..2 { execute(tx, &big("y"))?; } Ok(()) }); assert!(ok.is_ok()); let rows = bounded_rows(&db, "t", usize::MAX, usize::MAX).unwrap(); assert_eq!(rows[0][1], Value::Text("y".repeat(60000))); let over = db.transaction(true, |tx| { for _ in 0..3 { execute(tx, &big("z"))?; } Ok(()) }); assert!(over.is_err()); let rows = bounded_rows(&db, "t", usize::MAX, usize::MAX).unwrap(); assert_eq!(rows.len(), 200); assert_eq!(rows[0][1], Value::Text("y".repeat(60000))); execute(&db, "UPDATE t SET v = 'small' WHERE id = 1").unwrap(); let _ = std::fs::remove_dir_all(&dir); }
#[test]fn too_many_entries_in_one_transaction_is_rolled_back() { let dir = std::env::temp_dir().join(format!("parth_overlay_count_{}", std::process::id())); let _ = std::fs::remove_dir_all(&dir); let db = Database::open(&dir).unwrap(); execute(&db, "CREATE TABLE t (id INT PRIMARY KEY)").unwrap(); let over = db.transaction(true, |tx| { for i in 0..100001 { execute(tx, &format!("INSERT INTO t VALUES ({})", i))?; } Ok(()) }); assert!(over.is_err()); let rows = bounded_rows(&db, "t", usize::MAX, usize::MAX).unwrap(); assert_eq!(rows.len(), 0); execute(&db, "INSERT INTO t VALUES (1)").unwrap(); let _ = std::fs::remove_dir_all(&dir); }